\begin{proof}
For each $n\in\mathbb{N}$, the ball $B(n,1/2)$ in the usual metric on $\mathbb{N}$ is $\{n\}$, so every singleton is open. Any subset $A\subseteq\mathbb{N}$ is the union $A=\bigcup_{n\in A}\{n\}$ and is therefore open. Applying the same argument to $\mathbb{N}\setminus A$ shows that the complement of $A$ is open. Hence $A$ is closed as well, so every subset of $\mathbb{N}$ is clopen.
\end{proof}

\begin{proof}
Let $A\subseteq\mathbb{N}$. If $n\in\mathbb{N}$, then for every $m\in\mathbb{N}$, $d(m,n)<1/2$ implies $m=n$, because distinct natural numbers have distance at least $1$. Thus $\{n\}=B(n,1/2)$ is open. Consequently,
\[
A=\bigcup_{n\in A}\{n\}
\]
is open. Its complement is likewise a union of open singletons, so $\mathbb{N}\setminus A$ is open. Therefore $A$ is closed, and hence clopen.
\end{proof}

\begin{proof}
Fix any subset $A\subseteq\mathbb{N}$. In the usual metric, if $m,n\in\mathbb{N}$ and $m\ne n$, then $d(m,n)=|m-n|\ge 1$. Hence $B(n,1/2)=\{n\}$ for every $n\in\mathbb{N}$, so every singleton is open. Since $A$ is a union of these singletons, $A$ is open. The same reasoning applies to $\mathbb{N}\setminus A$, which is therefore open; consequently $A$ is closed. Thus $A$ is clopen.
\end{proof}
